// implied_vol.cpp - C++17 reference: Newton-Raphson implied volatility
// with a bracketed bisection fallback. Compile: g++ -std=c++17 -O2 implied_vol.cpp
#include <cmath>
#include <cstdio>
#include <stdexcept>

constexpr double kPi = std::acos(-1.0);

double normCdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }
double normPdf(double x) { return std::exp(-0.5 * x * x) / std::sqrt(2.0 * kPi); }

struct Quote { double price, vega; };

Quote bsCall(double S, double K, double r, double T, double sigma) {
    double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
    double d2 = d1 - sigma * std::sqrt(T);
    double price = S * normCdf(d1) - K * std::exp(-r * T) * normCdf(d2);
    return {price, S * std::sqrt(T) * normPdf(d1)};
}

double impliedVol(double price, double S, double K, double r, double T,
                  double sigma0 = 0.5, double tol = 1e-10, int maxIter = 50) {
    const double lo = 1e-9, hi = 5.0;
    double pLo = bsCall(S, K, r, T, lo).price, pHi = bsCall(S, K, r, T, hi).price;
    if (price <= pLo || price >= pHi)
        throw std::invalid_argument("quote outside no-arbitrage band (S - K e^-rT, S)");

    double sigma = sigma0;
    for (int it = 0; it < maxIter; ++it) {
        Quote q = bsCall(S, K, r, T, sigma);
        double nxt = sigma - (q.price - price) / q.vega;      // Newton step
        if (q.vega < 1e-8 || nxt <= lo || nxt >= hi) break;   // safeguard -> bisection
        std::printf("  newton  it=%d  sigma=%.6f  price=%.6f  resid=%+.6f  vega=%.4f\n",
                    it, sigma, q.price, q.price - price, q.vega);
        sigma = nxt;
        if (std::fabs(q.price - price) < tol) return sigma;
    }
    std::printf("  falling back to bisection\n");
    double a = lo, b = hi;
    for (int it = 0; it < 200; ++it) {
        double mid = 0.5 * (a + b);
        if (bsCall(S, K, r, T, mid).price > price) b = mid; else a = mid;
        if (b - a < 1e-12) break;
    }
    return 0.5 * (a + b);
}

int main() {
    double vol = impliedVol(10.4506, 100.0, 100.0, 0.05, 1.0);
    std::printf("sigma* = %.6f\n", vol);
    double vol2 = impliedVol(0.0100, 100.0, 180.0, 0.05, 0.05);
    std::printf("deep OTM: sigma* = %.6f\n", vol2);
}

